import { computed, defineComponent, h, inject, provide, ref, type ComputedRef, type InjectionKey, type PropType } from 'vue';
import { clampSliderValue, getSliderOffsetStyle, getSliderPercent, sliderStyleKeys } from '../lib/core';
import type { SliderOrientation } from '../lib/core';
import styles from './slider.module.scss';

interface SliderContextValue {
	value: number;
	min: number;
	max: number;
	step: number;
	orientation: SliderOrientation;
	disabled: boolean;
	setValue: (value: number) => void;
}

type SliderContext = ComputedRef<SliderContextValue>;

const SliderContextKey: InjectionKey<SliderContext> = Symbol('tile-slider');

export const Slider = defineComponent({
	name: 'Slider',
	props: {
		modelValue: { type: Number, default: undefined },
		defaultValue: { type: Number, default: 0 },
		min: { type: Number, default: 0 },
		max: { type: Number, default: 100 },
		step: { type: Number, default: 1 },
		orientation: {
			type: String as PropType<SliderOrientation>,
			default: 'horizontal',
		},
		disabled: { type: Boolean, default: false },
	},
	emits: ['update:modelValue', 'change'],
	setup(props, { emit, slots }) {
		const internalValue = ref(props.defaultValue);
		const currentValue = computed(() => (props.modelValue !== undefined ? props.modelValue : internalValue.value));
		const clampedValue = computed(() => clampSliderValue(currentValue.value, props.min, props.max));

		function setValue(next: number) {
			if (props.disabled) {
				return;
			}
			const clamped = clampSliderValue(next, props.min, props.max);
			const stepped = clampSliderValue(props.min + Math.round((clamped - props.min) / props.step) * props.step, props.min, props.max);
			if (props.modelValue === undefined) {
				internalValue.value = stepped;
			}
			emit('update:modelValue', stepped);
			emit('change', stepped);
		}

		function updateFromEvent(event: PointerEvent, element: HTMLElement) {
			const rect = element.getBoundingClientRect();
			let next: number;
			if (props.orientation === 'vertical') {
				next = props.min + ((event.clientY - rect.top) / rect.height) * (props.max - props.min);
			} else {
				next = props.min + ((event.clientX - rect.left) / rect.width) * (props.max - props.min);
			}
			setValue(next);
		}

		function handlePointerdown(event: PointerEvent) {
			if (props.disabled) {
				return;
			}
			const current = event.currentTarget as HTMLElement;
			current.setPointerCapture(event.pointerId);
			updateFromEvent(event, current);
		}

		function handlePointermove(event: PointerEvent) {
			if (props.disabled) {
				return;
			}
			const current = event.currentTarget as HTMLElement;
			if (!current.hasPointerCapture(event.pointerId)) {
				return;
			}
			updateFromEvent(event, current);
		}

		const context = computed<SliderContextValue>(() => ({
			value: clampedValue.value,
			min: props.min,
			max: props.max,
			step: props.step,
			orientation: props.orientation,
			disabled: props.disabled,
			setValue,
		}));

		provide(SliderContextKey, context);

		return () =>
			h(
				'div',
				{
					class: styles[sliderStyleKeys.root],
					'data-orientation': props.orientation,
					'data-disabled': props.disabled,
					onPointerdown: handlePointerdown,
					onPointermove: handlePointermove,
				},
				slots.default?.(),
			);
	},
});

export const SliderTrack = defineComponent({
	name: 'SliderTrack',
	setup(_props, { slots }) {
		const context = inject(SliderContextKey);
		if (!context) {
			throw new Error('SliderTrack must be used within <Slider>.');
		}

		return () => h('div', { class: styles[sliderStyleKeys.track], 'data-orientation': context.value.orientation }, slots.default?.());
	},
});

export const SliderRange = defineComponent({
	name: 'SliderRange',
	setup(_props) {
		const context = inject(SliderContextKey);
		if (!context) {
			throw new Error('SliderRange must be used within <Slider>.');
		}

		return () => {
			const percent = getSliderPercent(context.value.value, context.value.min, context.value.max);
			const style = context.value.orientation === 'vertical' ? { height: `${percent}%` } : { width: `${percent}%` };
			return h('div', { class: styles[sliderStyleKeys.range], 'data-orientation': context.value.orientation, style });
		};
	},
});

export const SliderThumb = defineComponent({
	name: 'SliderThumb',
	setup(_props) {
		const contextValue = inject(SliderContextKey);
		if (!contextValue) {
			throw new Error('SliderThumb must be used within <Slider>.');
		}
		const context: SliderContext = contextValue;

		function handleKeydown(event: KeyboardEvent) {
			const { value, min, max, step, orientation } = context.value;

			if (event.key === 'Home') {
				context.value.setValue(min);
				event.preventDefault();
				return;
			}

			if (event.key === 'End') {
				context.value.setValue(max);
				event.preventDefault();
				return;
			}

			let delta = 0;
			if (orientation === 'horizontal') {
				if (event.key === 'ArrowRight') {
					delta = 1;
				} else if (event.key === 'ArrowLeft') {
					delta = -1;
				}
			} else if (event.key === 'ArrowDown') {
				delta = 1;
			} else if (event.key === 'ArrowUp') {
				delta = -1;
			}

			if (delta !== 0) {
				context.value.setValue(value + delta * step);
				event.preventDefault();
			}
		}

		return () =>
			h('span', {
				role: 'slider',
				tabindex: context.value.disabled ? -1 : 0,
				'aria-disabled': context.value.disabled,
				'aria-valuemin': context.value.min,
				'aria-valuemax': context.value.max,
				'aria-valuenow': context.value.value,
				'aria-orientation': context.value.orientation,
				'data-orientation': context.value.orientation,
				class: styles[sliderStyleKeys.thumb],
				style: getSliderOffsetStyle(context.value.value, context.value.min, context.value.max, context.value.orientation),
				onKeydown: handleKeydown,
			});
	},
});

export default Slider;

@use '../../../styles/variables/colors' as *;

.root {
	position: relative;
	display: flex;
	width: 100%;
	align-items: center;
	touch-action: none;
	user-select: none;
	padding: var(--tile-slider-padding, 0);
	border-radius: var(--tile-slider-radius, 0);
	background-color: var(--tile-slider-background, transparent);
	box-shadow: var(--tile-slider-shadow, none);

	&[data-orientation='vertical'] {
		width: auto;
		height: 100%;
		min-height: 11rem;
		flex-direction: column;
	}

	&[data-disabled='true'] {
		opacity: 0.5;
	}
}

.track {
	position: relative;
	flex-grow: 1;
	overflow: hidden;
	border-radius: var(--tile-slider-track-radius, #{$radius-full});
	background-color: var(--tile-slider-track-background, #{$muted});

	[data-orientation='horizontal'] & {
		height: var(--tile-slider-track-size, 0.375rem);
		width: 100%;
	}

	[data-orientation='vertical'] & {
		height: 100%;
		width: var(--tile-slider-track-size, 0.375rem);
	}
}

.range {
	position: absolute;
	top: 0;
	left: 0;
	background-color: var(--tile-slider-range-background, #{$primary});
	border-radius: var(--tile-slider-range-radius, 0);
	box-shadow: var(--tile-slider-range-shadow, none);

	[data-orientation='horizontal'] & {
		height: 100%;
	}

	[data-orientation='vertical'] & {
		width: 100%;
	}
}

.thumb {
	position: absolute;
	display: block;
	width: var(--tile-slider-thumb-width, 1rem);
	height: var(--tile-slider-thumb-height, 1rem);
	border: var(--tile-slider-thumb-border-width, 1px) solid var(--tile-slider-thumb-border, #{$primary});
	border-radius: var(--tile-slider-thumb-radius, #{$radius-full});
	background-color: var(--tile-slider-thumb-background, #{$background});
	box-shadow: var(--tile-slider-thumb-shadow, #{$shadow-sm});
	transition: box-shadow $transition-fast;
	outline: none;
	cursor: grab;

	&:active {
		cursor: grabbing;
	}

	&:focus-visible {
		box-shadow: var(--tile-slider-thumb-focus-shadow, 0 0 0 1px $ring, 0 0 0 4px color-mix(in srgb, $ring 50%, transparent));
	}

	[data-orientation='horizontal'] & {
		top: 50%;
		transform: translate(-50%, -50%);
	}

	[data-orientation='vertical'] & {
		left: 50%;
		transform: translate(-50%, -50%);
	}
}
